import java.util.*;

class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];
        for (int i = 0; i < n; i++) {
            int l = leftChild[i];
            int r = rightChild[i];
            if (l != -1) {
                indegree[l]++;
                if (indegree[l] > 1) return false; // a node has more than one parent
            }
            if (r != -1) {
                indegree[r]++;
                if (indegree[r] > 1) return false;
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) return false; // more than one root
                root = i;
            }
        }
        if (root == -1) return false; // no root

        boolean[] visited = new boolean[n];
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dq.add(root);
        visited[root] = true;
        int count = 0;
        while (!dq.isEmpty()) {
            int node = dq.poll();
            count++;
            int l = leftChild[node];
            int r = rightChild[node];
            if (l != -1) {
                if (visited[l]) return false; // cycle or multiple parents (caught here)
                visited[l] = true;
                dq.add(l);
            }
            if (r != -1) {
                if (visited[r]) return false;
                visited[r] = true;
                dq.add(r);
            }
        }
        return count == n;
    }
}

